all.css:
.pageBackground {
  overflow: hidden;
}

/* Sky first, water last. The whole scene is static on purpose: PageBackground drops the glass blur
   for any background that declares keyframes, and the blur is the point of this palette. */
.aeroSky {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(to bottom, #f2faff 0%, #d8ecfb 34%, #b3daf1 68%, #8cc6e6 100%);
}

/* The light source, high and off to one side, where a Vista wallpaper puts it. */
.aeroBloom {
  position: absolute;
  inset: -25% -12% auto -12%;
  height: 80%;
  background:
    radial-gradient(46% 66% at 78% 8%, rgba(255,255,255,.90) 0%, rgba(255,255,255,.34) 32%, rgba(255,255,255,0) 70%);
  filter: blur(8px);
}

.aeroBubbles {
  position: absolute;
  inset: 0;
  background-image:
    radial-gradient(circle at 38% 32%, rgba(255,255,255,.92) 0 4%, rgba(255,255,255,.30) 34%, rgba(255,255,255,.10) 62%, rgba(255,255,255,0) 70%),
    radial-gradient(circle at 42% 30%, rgba(255,255,255,.85) 0 5%, rgba(255,255,255,.24) 32%, rgba(255,255,255,.08) 60%, rgba(255,255,255,0) 68%),
    radial-gradient(circle at 36% 34%, rgba(255,255,255,.80) 0 4%, rgba(214,240,255,.26) 30%, rgba(214,240,255,.08) 58%, rgba(214,240,255,0) 66%),
    radial-gradient(circle at 40% 30%, rgba(255,255,255,.70) 0 5%, rgba(255,255,255,.18) 30%, rgba(255,255,255,0) 64%);
  background-size: 260px 260px, 170px 170px, 120px 120px, 90px 90px;
  background-position: 12% 22%, 74% 58%, 30% 76%, 88% 14%;
  background-repeat: no-repeat;
  opacity: .55;
}

/* The horizon: a wash of green under the blue, kept faint so it looks like haze and not as ground. */
.aeroGloss {
  position: absolute;
  inset: auto 0 0 0;
  height: 42%;
  background:
    linear-gradient(to top, rgba(122,206,178,.34) 0%, rgba(140,214,190,.14) 34%, rgba(255,255,255,0) 100%),
    radial-gradient(120% 70% at 50% 118%, rgba(255,255,255,.40) 0%, rgba(255,255,255,0) 62%);
  filter: blur(6px);
}

