/* Water rather than haze: a band of light across the lower third, the way a surface catches sun. */
.aeroGloss {
  position: absolute;
  inset: auto 0 0 0;
  height: 48%;
  background:
    linear-gradient(to top, rgba(72,168,206,.38) 0%, rgba(120,204,222,.16) 40%, rgba(255,255,255,0) 100%),
    repeating-linear-gradient(96deg,
      rgba(255,255,255,0) 0 26px,
      rgba(255,255,255,.16) 26px 34px,
      rgba(255,255,255,0) 34px 74px);
  mask-image: linear-gradient(to top, #000 0%, rgba(0,0,0,.35) 55%, transparent 100%);
  filter: blur(5px);
}

